#ifndef MT6688_REG_DEF_H
#define MT6688_REG_DEF_H

/* REGBK TOP */
#define MT6688_TOP_CTRL1                    0x004

/* REGBK UDS */
#define MT6688_UDS_CTRL2_ADDR	            0x0300
#define MT6688_UDS_GPIO1_ADDR	            0x0301
#define MT6688_UDS_GPIO2_ADDR	            0x0302
#define MT6688_UDS_SEQON_VCK12_ADDR	        0x0303
#define MT6688_UDS_SEQON_VCK18_ADDR	        0x0304
#define MT6688_UDS_SEQON_AUX18_ADDR	        0x0305
#define MT6688_UDS_SEQON_EXT_CLK_EN_ADDR	0x0306

/* REGBK LDO */
#define MT6688_LDO_VCK12_OP_EN4_ADDR        0x0609
#define MT6688_LDO_VCK12_OP_CFG4_ADDR       0x060E
#define MT6688_LDO_VCK12_OP_MODE4_ADDR      0x0613
#define MT6688_LDO_VCK18_OP_EN4_ADDR        0x0629
#define MT6688_LDO_VCK18_OP_CFG4_ADDR       0x062E
#define MT6688_LDO_VCK18_OP_MODE4_ADDR      0x0633


#endif /* MT6688_REG_DEF_H */
